import{_ as r,a8 as a,o as i,c as n,ah as s,K as t}from"./chunks/framework.CIrX4_tc.js";import"./chunks/theme.DhGbIGPm.js";const u=JSON.parse('{"title":"300法则","description":"","frontmatter":{"title":"300法则","abstract":"目标管理法则——100%清晰度、100%信念与100%的时间三者缺一不可，通过设计环境、管理能量与建立成就清单让目标不动摇。","created":"2026-07-02T00:00:00.000Z","tags":["学习方法","目标管理","信念"],"type":"概念解释","related":["[[📚 个人知识管理-MOC]]","[[环境塑造与个人改变]]"],"reference":null,"category":["📚 个人知识管理","个人能力"]},"headers":[],"relativePath":"vault/Knowledge/Methods/300法则.md","filePath":"vault/Knowledge/Methods/300法则.md","lastUpdated":1790655645000}'),h={name:"vault/Knowledge/Methods/300法则.md"};function d(c,e,_,f,p,m){const l=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return i(),n("div",null,[e[0]||(e[0]=s('<h1 id="_300-法则" tabindex="-1">300%法则 <a class="header-anchor" href="#_300-法则" aria-label="Permalink to “300%法则”">​</a></h1><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h2><p>300% 法则 = 100% 清晰度 × 100% 信念 × 100% 的时间。三者缺一不可，一旦有一个打折，目标就会动摇。</p><hr><h2 id="_100-clarity-100-的清晰度" tabindex="-1">100% clarity，100% 的清晰度 <a class="header-anchor" href="#_100-clarity-100-的清晰度" aria-label="Permalink to “100% clarity，100% 的清晰度”">​</a></h2><p>明确的告诉别人你的目标，让别人来帮助你。我们不是创造未来，而是吸引未来。如何做？</p><ol><li><strong>Dream big</strong> — 做大梦，要有一个很长远的、很不可思议的目标</li><li><strong>Shop your dreams</strong> — 去感受梦想中的生活，熟悉它</li><li><strong>Write down</strong> — 写下来，写下来才能更好的实现</li><li><strong>Create vision board</strong> — 创造愿景板，将目标视觉化</li></ol><h2 id="_100-belief-100-的信念" tabindex="-1">100% Belief，100%的信念 <a class="header-anchor" href="#_100-belief-100-的信念" aria-label="Permalink to “100% Belief，100%的信念”">​</a></h2><ol><li>限制性信念，认为自己不足</li><li>负面信念，认为富人怎么怎么不好，最终导致自己胆小怕事</li><li>积极信念，你有想法那就有可能实现，没有东西是本来就存在</li></ol><h2 id="_100-of-the-time-100-的时间" tabindex="-1">100% of the time，100% 的时间 <a class="header-anchor" href="#_100-of-the-time-100-的时间" aria-label="Permalink to “100% of the time，100% 的时间”">​</a></h2><p>如果没有100%的时间都保持清晰度和信念，那就不会有动力</p><h2 id="the-rule-of-300-300-法则" tabindex="-1">The rule of 300%，300%法则 <a class="header-anchor" href="#the-rule-of-300-300-法则" aria-label="Permalink to “The rule of 300%，300%法则”">​</a></h2><p>如何对自己的目标保持 100% 的清晰度，100% 相信自己能够实现它，并且 100% 的时间保持这种状态——这样就不会动摇。</p><ol><li>设计自己的环境，让身边围绕能帮助自己实现目标的人</li><li>管理自己的能量——没人想帮助负能量的人</li><li>建立自己的成就清单，时刻提醒自己有多棒</li></ol>',14)),t(l),t(o)])}const P=r(h,[["render",d]]);export{u as __pageData,P as default};
